552	// checkCampaignBatchRelease 核对活动的批次放行顺序与保存的升级结果自洽：
553	// 任一已经领取过下载的设备，在其首次领取下载时，所有较早批次的设备都必须
554	// 已经成功完成安装，且每台前序设备首次接受安装成功结果的时间不晚于该次
555	// 下载的首次领取时间。只按活动保存的升级结果判断：设备当前是否在线、当前
556	// 版本是否恰好等于目标版本都不能替代前序安装成功；前序设备仅下载成功、
557	// 正在安装、安装失败后等待回滚或已经回滚成功均不满足放行条件。
558	// 尚未领取下载的设备（正常等待后批、因前批失败而未执行、未领取即随截止
559	// 超时）不参与核对，也不能仅因前批没有成功而拒绝。时间按同一时刻比较，
560	// 时区写法不同不视为矛盾；同一时刻合法。核对对仍在执行和已结束的活动都
561	// 生效，下载后来成功、失败或超时都不能掩盖首次领取时越过前批的问题。
562	func checkCampaignBatchRelease(campaignID string, c *campaignState) error {
563		for _, cd := range c.Devices {
564			if !cd.Download.Claimed || cd.Download.ClaimedAt.IsZero() {
565				continue
566			}
567			claimedAt := cd.Download.ClaimedAt
568			for _, prev := range c.Devices {
569				if prev.Batch >= cd.Batch {
570					// 同批设备各自推进，不等待同批其他设备；更晚批次不相关。
571					continue
572				}
573				if !(prev.Install.HasResult && prev.Install.Success) {
574					return fmt.Errorf("%w: campaign %s device %s download claimed while previous-batch device %s not installed",
575						ErrCorruptStorage, campaignID, cd.DeviceID, prev.DeviceID)
576				}
577				// time.Time 的比较按绝对时刻进行，不因时区写法不同而拒绝
578				// 相同时刻；安装成功时刻晚于下载领取时刻即属越批领取，相等合法。
579				if prev.Install.At.After(claimedAt) {
580					return fmt.Errorf("%w: campaign %s device %s download claimed at %s before device %s install succeeded at %s",
581						ErrCorruptStorage, campaignID, cd.DeviceID,
582						claimedAt.Format(time.RFC3339Nano), prev.DeviceID, prev.Install.At.Format(time.RFC3339Nano))
583				}
584			}
585		}
586		return nil
587	}
