139			in, _ := s.Claim(spec.ID, "d1", upBase.Add(15*time.Minute))
140			if err := s.SubmitResult(OperationResult{
141				CampaignID: spec.ID, DeviceID: "d1", OperationID: in.ID,
142				At: upBase.Add(20 * time.Minute), Success: false, Reason: "install boom",
143			}); err != nil {
