275		// 首次领取时因版本不兼容直接形成下载失败：领取与失败是同一时刻，
276		// 必须正常保留并打开。
277		t.Run("incompatible claim failure same instant", func(t *testing.T) {
278			s := setupUpgrade(t, "d1")
279			spec := upSpec()
