283			bringOnline(t, s, "d1")
284			if err := s.Report("d1", 2, upBase.Add(time.Minute), "v9", json.RawMessage(`{}`)); err != nil {
285				t.Fatal(err)
286			}
287			incompatAt := upBase.Add(2 * time.Minute)
288			if _, err := s.Claim(spec.ID, "d1", incompatAt); !errors.Is(err, ErrIncompatibleVersion) {
289				t.Fatalf("incompatible claim: %v", err)
290			}
291			dir := closeStore(t, s)
292			s2, err := Open(dir)
293			if err != nil {
294				t.Fatalf("claim-time failure must open: %v", err)
295			}
296			defer s2.Close()
297			cv := mustGetCampaign(s2, spec.ID)
298			d := findDevice(cv, "d1")
299			if d.Status != DeviceFailed || d.Phase != StageDownload {
300				t.Fatalf("download failure state lost: %+v", d)
301			}
302		})
303	
304		// 窗口内领取、窗口结束后截止前提交结果合法：结果时间不要求在维护窗口内。
305		t.Run("result after window before deadline opens", func(t *testing.T) {
306			s := setupUpgrade(t, "d1")
307			spec := upSpec()
308			spec.Devices = []string{"d1"}
309			createCampaign(t, s, spec)
310			bringOnline(t, s, "d1")
311			dl, _ := s.Claim(spec.ID, "d1", upBase.Add(50*time.Minute))
312			if err := s.SubmitResult(OperationResult{
313				CampaignID: spec.ID, DeviceID: "d1", OperationID: dl.ID,
314				At: upBase.Add(80 * time.Minute), Success: true,
315			}); err != nil {
316				t.Fatal(err)
317			}
318			dir := closeStore(t, s)
319			s2, err := Open(dir)
320			if err != nil {
321				t.Fatalf("result outside window must open: %v", err)
322			}
323			defer s2.Close()
324		})
325	
326		// 已领取但尚未接受结果、仍在执行的操作没有结果时间，不触发本项核对。
327		t.Run("claimed without result opens", func(t *testing.T) {
328			_, dir, spec := setupDownloading(t)
329			s2, err := Open(dir)
330			if err != nil {
331				t.Fatalf("claimed unfinished operation must open: %v", err)
332			}
333			defer s2.Close()
334			if findDevice(mustGetCampaign(s2, spec.ID), "d1").Status != DeviceDownloading {
335				t.Fatalf("d1 progress lost")
336			}
337		})
338	
339		// 已领取未完成、随后随截止超时：超时记录没有结果时间，正常打开。
340		t.Run("claimed then timed out opens", func(t *testing.T) {
341			s := setupUpgrade(t, "d1")
342			spec := upSpec()
343			spec.Devices = []string{"d1"}
344			createCampaign(t, s, spec)
345			bringOnline(t, s, "d1")
346			if _, err := s.Claim(spec.ID, "d1", upBase.Add(10*time.Minute)); err != nil {
347				t.Fatalf("claim: %v", err)
348			}
349			if err := s.AdvanceCampaign(spec.ID, spec.Deadline); err != nil {
