362	
363		// 未领取的等待步骤（等待下载、因前批失败而未执行）没有领取与结果时间，
364		// 沿用原规则正常打开。
365		t.Run("unclaimed and skipped devices open", func(t *testing.T) {
366			s := setupUpgrade(t, "d1", "d2")
367			spec := upSpec()
